const refreshRepoPackageStats = `-- name: RefreshRepoPackageStats :one
WITH stats AS (
    SELECT
        p.id,
        COALESCE(SUM(f.size_bytes), 0)::bigint AS package_bytes,
        COALESCE((
            SELECT v.version
            FROM repo_package_versions v
            WHERE v.package_id = p.id
            ORDER BY v.created_at DESC, v.id DESC
            LIMIT 1
        ), '') AS latest_version
    FROM repo_packages p
    LEFT JOIN repo_package_versions v ON v.package_id = p.id
    LEFT JOIN repo_package_files f ON f.version_id = v.id
    WHERE p.id = $1::bigint
    GROUP BY p.id
)
UPDATE repo_packages p
   SET package_bytes = stats.package_bytes,
       latest_version = stats.latest_version,
       updated_at = now()
FROM stats
WHERE p.id = stats.id
RETURNING p.id, p.repo_id, p.name, p.normalized_name, p.package_type, p.description, p.latest_version, p.package_bytes, p.created_by_user_id, p.updated_by_user_id, p.created_at, p.updated_at
`

